WITH exploded AS (SELECT id, service, host, log_ts, latency_ms, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, attr_value) SELECT id, service, host, k, attr_value, NTILE(5) OVER w_hist AS latency_ms_bucket, NTILE(4) OVER w_grp AS latency_ms_bucket_2, SUM(latency_ms) OVER (PARTITION BY host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS latency_ms_sum_15m, AVG(latency_ms) OVER (PARTITION BY DATE_TRUNC('month', log_ts), host ORDER BY latency_ms, id, k ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS latency_ms_avg_6 FROM exploded WINDOW w_hist AS (ORDER BY latency_ms, id, k), w_grp AS (PARTITION BY host ORDER BY latency_ms, id, k)
